package com.fincore.fincore.budget; import java.util.List; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import com.fincore.fincore.security.AuthenticatedUser; @RestController @RequestMapping("/api/v1/budgets") public class BudgetController{private final BudgetService service;public BudgetController(BudgetService s){service=s;}@PostMapping ResponseEntity<BudgetResponse> create(@AuthenticationPrincipal AuthenticatedUser u,@Valid @RequestBody CreateBudgetRequest r){return ResponseEntity.status(201).body(service.create(u.id(),r));}@GetMapping List<BudgetResponse> all(@AuthenticationPrincipal AuthenticatedUser u){return service.all(u.id());}@PutMapping("/{id}") BudgetResponse update(@AuthenticationPrincipal AuthenticatedUser u,@PathVariable Long id,@Valid @RequestBody UpdateBudgetRequest r){return service.update(u.id(),id,r);}@DeleteMapping("/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)void delete(@AuthenticationPrincipal AuthenticatedUser u,@PathVariable Long id){service.delete(u.id(),id);}}
